import {Vector3,Vector4,Matrix3,ShaderChunk} from 'three';
import {probeVolumeGLSL,probeVolumeWeight} from './reflection-probe-volume.js';

export const reflectionProbeBlendContract=Object.freeze({version:6,component:'ReflectionProbe',selection:'importance, affine volume size, stable ID; direct pair when mesh bounds overlap at most two; otherwise spatial BVH per-fragment two lowest original ranks from the complete HDR atlas, including instance world positions',blend:'per-fragment affine face distance; a/max(1,a+b), b/max(1,a+b), base=1-min(1,a+b); intensity zero retains coverage; diffuseIntensity independent',lobes:'browser radiance, diffuse/multiscattering and clearcoat; GPU refraction uses the same samples',instances:'instance world positions and aggregate bounds; pixels choose their own ranked pair through the global atlas when a batch spans more than two volumes',deformation:'current CPU skin/morph bounds, negative weights and attribute/bone/bind stamps; unchanged poses do not scan vertices; custom shader deformation/per-instance morph textures require an owner',environment:'original material map or scene environment; preserve corresponding intensity/rotation, lazy owned prefilter only for raw cube/equirectangular maps',resources:'one172032B CPU half-float anchor per active browser renderer; existing captures/base filters plus lazy heterogeneous HDR atlas and metadata only when a draw overlaps more than two; D3D GPU border compute only at capture/resolution changes; static transfers retained; dimensions bounded by device, no object/probe count ceiling; rank-preserving spatial BVH plus CPU broad phase; overlapping worst cases remain linear; no production pixel readback or extra lighting pass',sdk:'existing ReflectionProbes intensity/diffuse/refresh and Components/Scene functions and Blueprint nodes; same saved JSON/AI CAS',diagnosticsRoot:'renderer.probes',nativeDiagnosticsRoot:'renderer',nativeDiagnostics:Object.freeze(['probeAtlasCount','probeAtlasMapCount','probeAtlasLayoutBuilds','probeAtlasMetadataFastUpdates','probeAtlasCPUBytes','probeAtlasMetadataBytes','probeAtlasMetadataCalls','probeAtlasBytes','probeAtlasCopies','probeAtlasUploads','probeAtlasPaddingDispatches','probeAtlasSpatialNodes','probeAtlasSpatialBuilds','probeAtlasSpatialCPUBytes']),atlasContract:Object.freeze({browserRecordFloat4s:9,shapeFlags:"projection bit0, sphere bit1 in browser atlas faceScale.w/native options.w; direct browser options.w enabled bit0/sphere bit1",sphereRadius:"world units; owner transform moves offset but does not stretch radius",nativeRecordBytes:144,nativeTableStrideBytes:16,pixelCandidates:2,search:'stackless spatial BVH, subtree minimum rank, conservative rounded affine bounds',spatialFloat4sPerNode:3,spatialNodes:'2*probeCount-1',addressing:'split16-bit finite float words; integer GPU selection retains IDs above2^24',nativeMetadataCPU:'same source/affine settings path validates all edits before applying; skips layout/tree/whole packet; uint source index replaces repeated stamps',captureSharing:'source identity deduplicated HDR images; native SH unique source index in region.w, mip count in maximum.w; per-volume bounds/rank/light stay independent',metadataUpload:'browser changed rows across GL/GPU/fallback with pending/full ownership; native changed record ranges; static zero; spatial geometry change/full allocation uploads tree',allocation:'lazy; hardware texture dimensions, no object/probe count cap'}),diagnostics:Object.freeze(['count','captures','blendedMeshes','globalMeshes','atlas','baseFilters','baseMaps','anchorBytes','browserSelection'])});

export function reflectionProbeBlendWeights(probes,point){const values=probes.map(p=>probeVolumeWeight(p.localBox,point,p.p.blendDistance)),total=values.reduce((a,b)=>a+b,0);return {weights:values.map(v=>v/Math.max(1,total)),base:1-Math.min(1,total)};}
export function probeMapLayout(map){const image=map?.image,width=image?.width||1,height=image?.height||64;return [1/width,1/height,Math.log2(height)-2];}
export function probeBlendUniforms(){const result={hbProbeBaseMap:{value:null},hbProbeBaseRotation:{value:new Matrix3()},hbProbeBaseLayout:{value:new Vector3()},hbProbeBaseOptions:{value:new Vector3()}};for(let i=0;i<2;i++){for(const key of ['Center','Min','Max','FaceScale','Layout'])result['hbProbe'+key+i]={value:new Vector3()};for(const key of ['LocalX','LocalY','LocalZ','Options'])result['hbProbe'+key+i]={value:new Vector4()};result['hbProbeIntensity'+i]={value:0};result['hbProbeMap'+i]={value:null};}return result;}
export function updateProbeBlendUniforms(u,probes,maps,base,intensity,rotation){if(rotation)u.hbProbeBaseRotation.value.copy(rotation);u.hbProbeBaseMap.value=base||maps[0]||maps[1]||null;u.hbProbeBaseLayout.value.fromArray(probeMapLayout(u.hbProbeBaseMap.value));u.hbProbeBaseOptions.value.set(base?1:0,intensity,0);for(let i=0;i<2;i++){const p=probes[i],map=maps[i]||maps[0]||maps[1]||base||null;u['hbProbeMap'+i].value=map;u['hbProbeLayout'+i].value.fromArray(probeMapLayout(map));u['hbProbeOptions'+i].value.set(p?.p.diffuseIntensity??1,p?.p.boxProjection?1:0,p?.p.blendDistance||0,p?(p.p.volumeShape==='sphere'?3:1):0);u['hbProbeIntensity'+i].value=p?.p.intensity||0;if(p){const b=p.localBox;u['hbProbeCenter'+i].value.fromArray(p.center);u['hbProbeMin'+i].value.fromArray(b.minimum);u['hbProbeMax'+i].value.fromArray(b.maximum);for(const key of ['LocalX','LocalY','LocalZ','FaceScale'])u['hbProbe'+key+i].value.fromArray(b[key[0].toLowerCase()+key.slice(1)]);}}}

// Three's licensed CubeUV addressing, with layout passed per texture instead of
// global defines. Different probe resolutions share the same compiled program.
const cubeChunk=ShaderChunk.cube_uv_reflection_fragment,sampleStart=cubeChunk.indexOf('vec3 bilinearCubeUV'),sampleEnd=cubeChunk.indexOf('#define cubeUV_r0');
if(sampleStart<0||sampleEnd<=sampleStart)throw Error('설치된 Three의 CubeUV 샘플러 계약을 확인하세요.');
const sampler=cubeChunk.slice(sampleStart,sampleEnd)
 .replace('bilinearCubeUV( sampler2D envMap, vec3 direction, float mipInt )','hbProbeBilinear( sampler2D envMap, vec3 direction, float mipInt, vec3 cubeLayout )').replaceAll('CUBEUV_MAX_MIP','cubeLayout.z').replaceAll('CUBEUV_TEXEL_WIDTH','cubeLayout.x').replaceAll('CUBEUV_TEXEL_HEIGHT','cubeLayout.y');
export const probeBlendGLSL=probeVolumeGLSL+'\nvarying vec3 hbProbePosition;\n'+`
#ifdef ENVMAP_TYPE_CUBE_UV
uniform sampler2D hbProbeBaseMap;uniform mat3 hbProbeBaseRotation;uniform vec3 hbProbeBaseLayout,hbProbeBaseOptions;
${[0,1].map(i=>`uniform sampler2D hbProbeMap${i};uniform vec3 hbProbeCenter${i},hbProbeMin${i},hbProbeMax${i},hbProbeFaceScale${i},hbProbeLayout${i};uniform vec4 hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i},hbProbeOptions${i};uniform float hbProbeIntensity${i};`).join('\n')}
${sampler}
vec3 hbProbeSample(sampler2D map,vec3 direction,float roughness,vec3 cubeLayout){float mip=clamp(roughnessToMip(roughness),cubeUV_m0,cubeLayout.z),whole=floor(mip),fraction=fract(mip);vec3 first=hbProbeBilinear(map,direction,whole,cubeLayout);return fraction==0.0?first:mix(first,hbProbeBilinear(map,direction,whole+1.0,cubeLayout),fraction);}
${[0,1].map(i=>`float hbProbeFade${i}(){return min(hbProbeOptions${i}.w,1.0)*(hbProbeOptions${i}.w>1.5?hbProbeSphereFade(hbProbeLocalPoint(hbProbePosition,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeMax${i}.x,hbProbeOptions${i}.z):hbProbeVolumeFade(hbProbeLocalPoint(hbProbePosition,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeMin${i},hbProbeMax${i},hbProbeFaceScale${i},hbProbeOptions${i}.z));}
vec3 hbProbeRay${i}(vec3 ray){return hbProbeOptions${i}.y<.5?ray:hbProbeOptions${i}.w>1.5?hbProbeSphereProject(hbProbePosition,ray,hbProbeCenter${i},hbProbeLocalPoint(hbProbePosition,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeLocalRay(ray,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeMax${i}.x):hbProbeProject(hbProbePosition,ray,hbProbeCenter${i},hbProbeLocalPoint(hbProbePosition,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeLocalRay(ray,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeMin${i},hbProbeMax${i});}`).join('\n')}
vec3 hbProbeLight(vec3 ray,float roughness,bool diffuse){float a=hbProbeFade0(),b=hbProbeFade1(),total=a+b;vec3 light=vec3(0);if(a>0.0)light+=hbProbeSample(hbProbeMap0,diffuse?ray:hbProbeRay0(ray),roughness,hbProbeLayout0)*hbProbeIntensity0*(diffuse?hbProbeOptions0.x:1.0)*a;if(b>0.0)light+=hbProbeSample(hbProbeMap1,diffuse?ray:hbProbeRay1(ray),roughness,hbProbeLayout1)*hbProbeIntensity1*(diffuse?hbProbeOptions1.x:1.0)*b;light/=max(1.0,total);if(hbProbeBaseOptions.x>0.5&&total<1.0)light+=hbProbeSample(hbProbeBaseMap,hbProbeBaseRotation*ray,roughness,hbProbeBaseLayout)*hbProbeBaseOptions.y*(1.0-total);return light;}
#endif
`;
export function probeBlendPhysicalGLSL(){return probeBlendGLSL+'\n'+ShaderChunk.envmap_physical_pars_fragment.replace(/vec4 envMapColor = textureCubeUV\([^;]+;/g,'').replace('return PI * envMapColor.rgb * envMapIntensity;','return PI * hbProbeLight(worldNormal,1.0,true);').replace('return envMapColor.rgb * envMapIntensity;','return hbProbeLight(reflectVec,roughness,false);');}
